def simple(init,year,rate,fee):
    accum=0
    for i in range(year):
        accum+=int(init*rate)
        init-=fee
    return init+accum

def compound(init,year,rate,fee):
    for i in range(year):
        init+=int(init*rate-fee)
    return init

